  const editing = !!editingDayId;
  if (editing){
    const d = state.days.find(x => x.id === editingDayId);
    if (!d) return showToast('⚠️ This day no longer exists');
    d.name = name; d.color = selectedColor;
  } else state.days.push({id:makeId(), name, color:selectedColor, exercises:[]});
