  const img = new Image(), url = URL.createObjectURL(f);
  img.onload = () => { const s = Math.min(img.width, img.height), cv = document.createElement('canvas'); cv.width = cv.height = 192; cv.getContext('2d').drawImage(img, (img.width - s) / 2, (img.height - s) / 2, s, s, 0, 0, 192, 192); settings.avatar = cv.toDataURL('image/jpeg', .8); URL.revokeObjectURL(url); save(); renderChar(); renderHero(); showToast('📷 Photo saved'); };
