  $('modelSel').value = geminiModel(); $('gKeyInput').value = settings.geminiKey || ''; $('alStreak').checked = alertOn('streak'); $('alReport').checked = alertOn('report'); $('animOn').checked = settings.anim !== false; $('alPush').checked = !!settings.pushOn; $('pushTestBtn').onclick = pushTest;
