  if ((r.on || $('alStreak').checked || $('alReport').checked) && 'Notification' in window && Notification.permission === 'default') await Notification.requestPermission();
  if (r.on && (!('Notification' in window) || Notification.permission !== 'granted')){ r.on = false; showToast('⚠️ Reminders need notifications to be allowed.'); }
  settings.rem = r; settings.anim = $('animOn').checked; applyAnim(); settings.syncPass = $('syncPass').value; settings.autoSync = $('autoSync').checked;
  settings.geminiKey = $('gKeyInput').value.trim(); settings.alerts = {streak:$('alStreak').checked, report:$('alReport').checked}; $('coachMode').textContent = coachReady() ? '✨ Gemini' : 'Not connected';
  await pushApply();
