  readIntro(); const k = b.dataset.k; INTRO.d[k] = k === 'days' ? +b.dataset.v : b.dataset.v;
  b.parentElement.querySelectorAll('[data-k]').forEach(x => x.classList.toggle('sel', x === b)); buzz(8);
