$('intro').addEventListener('keydown', e => { if (e.key === 'Enter' && e.target.tagName === 'INPUT'){ e.preventDefault(); introNext(); } });
function moveDay(id, d){ const i = state.days.findIndex(x => x.id === id), j = i + d; if (i < 0 || j < 0 || j >= state.days.length) return; [state.days[i], state.days[j]] = [state.days[j], state.days[i]]; save(); renderAllViews(); }
function moveEx(id, k, d){ const day = state.days.find(x => x.id === id); if (!day) return; const j = k + d; if (j < 0 || j >= day.exercises.length) return; [day.exercises[k], day.exercises[j]] = [day.exercises[j], day.exercises[k]]; save(); renderAllViews(); }
