let TRAIN_DAY = null, TRAIN_ANIM = true, TRAIN_DIR = 0; const COLL = {};
const UNI_RE = /(single|one)[ -]?(arm|leg|hand)|unilateral|alternating|split squat|lunge|step-?up|bulgarian|concentration|dumbbell row|cossack|skater|pistol|curtsy|suitcase|kroc|meadows|helms|zottman|bottoms-up|landmine press|cable kickback|donkey|fire hydrant|clamshell|copenhagen|bird dog/i;
