  if (sn){ (logData.__notes = logData.__notes || {})[sn.dataset.sn] = sn.value; saveDraft(); return; }
  const inp = e.target.closest('[data-f]'); if (!inp) return;
  const d = logFor(inp); if (!d) return; const f = inp.dataset.f;
  if (f === 'rpe'){ d.rpe = inp.value ? +inp.value : null; saveDraft(); return; }
  if (f === 'note'){ d.note = inp.value.trim(); saveDraft(); return; }
  const s = d.sets[+inp.dataset.s]; if (!s) return;
  if (f === 'weight') s.weight = Math.max(0, fromDisp(parseFloat(inp.value) || 0));
  if (f === 'repsL' || f === 'repsR'){ if (s.repsL === undefined) s.repsL = s.reps; if (s.repsR === undefined) s.repsR = s.reps; s[f] = Math.max(0, parseInt(inp.value, 10) || 0); s.reps = uniReps(s); delete s.repsText; }
  if (f === 'reps'){ const r = parseReps(inp.value); s.reps = r.total; if (r.text) s.repsText = r.text; else delete s.repsText; }
  if (f === 'done'){ s.done = inp.checked; inp.closest('.srow').classList.toggle('done', s.done); if (s.done){ if (!workoutTimerStartedAt) startWorkoutTimer(); spark(inp); const ex = inp.closest('.ex'); if (ex && [...ex.querySelectorAll('input[data-f=done]')].every(c => c.checked)){ ex.classList.add('exdone'); buzz([20,40,30]); setTimeout(() => ex.classList.remove('exdone'), 750); } }
    if (s.done && !s.warm){ buzz(15); const xx = inp.closest('.ex'), dd = state.days.find(q => q.id === xx.dataset.d), ee = dd && dd.exercises[+xx.dataset.i]; if (!d.ss && settings.restAuto !== false) startRest((ee && ee.rest) || settings.rest || 90); } }
