  $('rsPresets').innerHTML = [30, 60, 90, 120, 180, 300].map(v => `<button type="button" class="sug" data-v="${v}">${v >= 60 && v % 60 === 0 ? (v / 60) + ' min' : v + 's'}</button>`).join('');
