  $('timerNum').textContent = Math.floor(left / 60) + ':' + String(left % 60).padStart(2, '0');
  $('timerBar').style.width = (restTotal > 0 ? Math.max(0, Math.min(100, left / restTotal * 100)) : 0) + '%';
