/* plate calculator */
function openPlates(){ $('plateTarget').value = isLb() ? 135 : 60; $('plateBar').value = isLb() ? 45 : 20; $('modalPlates').classList.add('active'); calcPlates(); }
function calcPlates(){
  const t = parseFloat($('plateTarget').value) || 0, bar = parseFloat($('plateBar').value) || 0, out = [], u = unitName(), plates = isLb() ? [45,35,25,10,5,2.5] : [25,20,15,10,5,2.5,1.25];
  let side = (t - bar) / 2;
  if (side < 0){ $('plateOut').textContent = 'Target is lighter than the bar.'; return; }
  plates.forEach(p => { const n = Math.floor(side / p + 1e-9); if (n){ out.push(`${n} × ${p}${u}`); side -= n * p; } });
  $('plateOut').textContent = (out.length ? 'Each side: ' + out.join(' + ') : 'Just the bar.') + (side > 0.01 ? ` (${(side * 2).toFixed(2)}${u} short)` : '');
}
