  if (authFailed || errors.some(e => / 40[13] /.test(e))) hint = ' || Key rejected. Create a NEW key at aistudio.google.com/apikey (use the key shown there, no spaces), make sure the Gemini API is enabled for its project, and paste it into APP_CONFIG.geminiKey.';
