/* ---------- warm-up sets ---------- */
function warmUp(){
  const t = parseFloat($('plateTarget').value) || 0, bar = parseFloat($('plateBar').value) || 0, u = unitName(), step = isLb() ? 5 : 2.5, o = $('warmOut');
  if (t <= bar * 1.3){ o.textContent = tr('Warm-up: just the bar is enough.'); return; }
  const r = x => Math.max(bar, Math.round(x / step) * step), w = [];
  [[bar, 10], [r(t * .5), 5], [r(t * .7), 3], [r(t * .85), 1]].forEach(x => { if (!w.length || w[w.length - 1][0] !== x[0]) w.push(x); });
  o.textContent = '🔥 ' + tr('Warm-up') + ': ' + w.map(x => x[0] + u + ' × ' + x[1]).join(' → ') + ' → ' + tr('then') + ' ' + t + u + ' ' + tr('working sets');
}
{ const _cp = calcPlates; calcPlates = function(){ _cp(); warmUp(); }; }

/* ---------- coach plan changes (user confirms) ---------- */
const cleanPlan = t => t.replace(/\[\[PLAN\]\][\s\S]*?(\[\[\/PLAN\]\]|$)/g, '').replace(/\[\[Q\]\][\s\S]*?(\[\[\/Q\]\]|$)/g, '').replace(/\[\[ACT\]\][\s\S]*?(\[\[\/ACT\]\]|$)/g, '').replace(/\[\[[A-Z\/]{0,5}$/, '').trim();
