function offerPlan(bubble, full){
  const items = [...full.matchAll(/\[\[PLAN\]\]([^\[]*?)\[\[\/PLAN\]\]/g)].map(m => m[1].split('|').map(x => x.trim()))
    .filter(c => c.length >= 3 && c[0] && c[2] && ['add','update','remove'].includes(c[1].toLowerCase()))
    .map(c => ({day:c[0], act:c[1].toLowerCase(), ex:c[2], sets:parseInt(c[3]), reps:c[4], w:parseFloat(c[5])}));
  if (!items.length) return;
  const u = unitName(), card = document.createElement('div'); card.className = 'msg ai plan-card';
  card.innerHTML = '🛠️ <b>Change your plan?</b><br>' + items.map(c => '• ' + escapeHTML(c.day) + ': ' + tr(c.act) + ' ' + escapeHTML(c.ex) + (c.act === 'remove' ? '' : ' ' + [c.sets ? c.sets + ' ' + tr('sets') : '', c.reps || '', isFinite(c.w) ? toDisp(c.w) + u : ''].filter(Boolean).join(' · '))).join('<br>') + '<br><button id="planYes">✅ Yes, apply</button><button class="sec" id="planNo">No, keep my plan</button>';
  bubble.after(card); $('chatMessages').scrollTop = 1e9;
  card.querySelector('#planNo').onclick = () => { card.remove(); showToast('👍 Plan unchanged'); };
  card.querySelector('#planYes').onclick = () => {
    items.forEach(c => {
      let d = state.days.find(x => sameEx(x.name, c.day));
      if (!d){ if (c.act !== 'add') return; d = {id:makeId(), name:c.day, color:'#3a7bd5', exercises:[]}; state.days.push(d); }
      const i = d.exercises.findIndex(e => sameEx(e.name, c.ex));
      if (c.act === 'remove'){ if (i > -1) d.exercises.splice(i, 1); return; }
      const old = i > -1 ? d.exercises[i] : {sets:3, reps:'8–12', weight:20};
      const ex = {name:i > -1 ? old.name : c.ex, sets:c.sets > 0 ? c.sets : old.sets, reps:c.reps || old.reps, weight:isFinite(c.w) && c.w >= 0 ? c.w : old.weight};
      if (i > -1) d.exercises[i] = Object.assign({}, old, ex); else d.exercises.push(ex);
    });
    save(); renderAllViews(); card.innerHTML = tr('✅ Plan updated.'); showToast('✅ Plan updated');
  };
}

