  const fu = followUps(full); if (fu.length){ const w = document.createElement('div'); w.className = 'qfu'; w.innerHTML = fu.map(q => `<button type="button" class="sec tiny">${escapeHTML(q)}</button>`).join(''); bubble.after(w); }
