  const rows = [['Report',title],['Summary',$('repVerdict').textContent||''],['Metric','Value','Details']];
  [...$('repGrid').children].forEach(el=>{ const t=el.querySelectorAll('b,small,em'); rows.push([t[1]?.textContent||'Metric',t[0]?.textContent||'',t[2]?.textContent||'']); });
