  $('consistencyChart').innerHTML = `<div class="bars" style="height:150px">${arr.map(([w,v]) => { const d = new Date(w); return `<div class="bw"><small>${v}</small><div class="bar1" style="height:${v / max * 100}%;background:${v >= g ? 'var(--ok)' : 'var(--inb)'}"></div><small>${d.getUTCMonth() + 1}/${d.getUTCDate()}</small></div>`; }).join('')}</div><small class="insight2">Green bars mean you reached your weekly goal.</small><p class="insight">${`You hit your weekly goal in ${hit} of the last 12 weeks.`}</p>`;
