$('rangeChips').addEventListener('click', e => { const b = e.target.closest('[data-r]'); if (!b) return; CH_RANGE = b.dataset.r; [...$('rangeChips').children].forEach(x => x.classList.toggle('sel', x === b)); renderCharts(); });
