  const nxt = state.days.find(d => d.id === nextDayId()) || state.days[0], dn = doneTodayDay(), day = dn || nxt, exs = (dn ? nxt : day).exercises || [], r = rpg(), wk = weekAgg()[weekStart(todayKey())] || {days:new Set()}, goal = weekGoal(), today = todayKey();
