  const ckb = (ckDue() && settings.weighSnooze !== todayKey()) ? `<div class="ckbanner"><div class="ckb-t"><b>📅 ${escapeHTML(tr('Monthly check-in'))}</b><small>${escapeHTML(tr(settings.ckSkips ? 'Still waiting for you. It takes one minute.' : 'Weight, a photo and 3 quick questions. See how you progressed.'))}</small></div><div class="ckb-b"><button type="button" onclick="openCheckin()">${escapeHTML(tr('Start'))}</button><button type="button" class="sec tiny" onclick="skipCheckin()">${escapeHTML(tr('Later'))}</button></div></div>` : '';
