      const n = c.querySelectorAll('.ex').length; if (st && !h.querySelector('small.cnt')) st.insertAdjacentHTML('afterend', '<small class="cnt">' + n + '</small>');
      c.classList.toggle('fold', !window._openDays.has(i));
