/* ---------- coach can read the Progress overview: exact numbers computed by the app ---------- */
function coachProgressBlock(){
  const today = todayKey(), goal = weekGoal(), L = ['PROGRESS OVERVIEW (exact numbers computed by the app from recorded data; do not invent values that are not listed, and say when data is missing):'];
  if (!sessions.length){ L.push('No sessions recorded yet.'); return L.join('\n'); }
  const sorted = sessions.slice().sort((a, b) => String(a.date).localeCompare(String(b.date))), first = localKey(sorted[0].date);
  const range = days => { const cut = shiftDays(today, -days), inR = sessions.filter(s => localKey(s.date) >= cut), from = first > cut ? first : cut, weeks = Math.max(1, Math.ceil((new Date(today) - new Date(from)) / 864e5 / 7)), dd = new Set(inR.map(s => localKey(s.date))).size;
    const timed = inR.filter(s => s.durationSec > 0), avg = timed.length ? Math.round(timed.reduce((a, s) => a + s.durationSec, 0) / timed.length / 60) : null;
    return `${days} days: ${inR.length} sessions on ${dd} training days vs ${weeks * goal} planned (${goal}/week goal), ${Math.round(inR.reduce((a, s) => a + (s.volume || 0), 0))} kg total volume, avg duration ${avg === null ? 'not tracked' : avg + ' min (' + timed.length + ' timed sessions)'}`; };
  L.push('Training consistency, ' + range(30)); L.push('Training consistency, ' + range(90));
  const wa = weekAgg(), wk = Object.keys(wa).sort().slice(-12); L.push('Weekly training days (oldest to newest, last ' + wk.length + ' weeks, goal ' + goal + '): ' + wk.map(k => wa[k].days.size).join(', ') + '. Goal weeks hit overall: ' + Object.values(wa).filter(w => w.days.size >= goal).length + '.');
  const wd = [0, 0, 0, 0, 0, 0, 0]; sessions.forEach(s => { wd[(new Date(localKey(s.date) + 'T12:00:00').getDay() + 6) % 7]++; }); L.push('Sessions by weekday (Mon..Sun): ' + wd.join(', ') + '.');
  const cut30 = shiftDays(today, -30), mus = {}; sessions.filter(s => localKey(s.date) >= cut30).forEach(s => s.exercises.forEach(e => { const l = LIB.find(x => x[0] === e.name), m = l ? (MUSCLES[l[1]] || l[1]) : 'Unclassified'; mus[m] = (mus[m] || 0) + e.sets.length; }));
  const me = Object.entries(mus).sort((a, b) => b[1] - a[1]); L.push('Working sets per muscle group, last 30 days: ' + (me.length ? me.map(x => x[0] + ' ' + x[1]).join(', ') : 'none') + '. Muscle groups with zero sets: ' + (Object.values(MUSCLES).filter(m => !mus[m]).join(', ') || 'none') + '.');
  const mo = []; for (let i = 5; i >= 0; i--){ const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i); const key = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'); mo.push(key + ':' + sessions.filter(s => localKey(s.date).slice(0, 7) === key).length); } L.push('Sessions per month: ' + mo.join(', ') + '.');
  const wsum = n => sessions.filter(s => { const k = localKey(s.date); return k > shiftDays(today, -7 * (n + 1)) && k <= shiftDays(today, -7 * n); }).length; L.push('Last 4 weeks: ' + (wsum(0) + wsum(1) + wsum(2) + wsum(3)) + ' sessions vs previous 4 weeks: ' + (wsum(4) + wsum(5) + wsum(6) + wsum(7)) + '.');
  const by = {}; sorted.forEach(s => s.exercises.forEach(e => { const w = Math.max(0, ...e.sets.map(x => +x.weight || 0)); if (w > 0){ const o = by[e.name] = by[e.name] || {first:w, best:w, n:0}; o.best = Math.max(o.best, w); o.n++; } }));
  const gains = Object.entries(by).filter(([, o]) => o.n >= 2).map(([n, o]) => [n, o.best - o.first, o.first, o.best]).sort((a, b) => b[1] - a[1]); L.push('Top-weight change since first logged (exercises logged 2+ times): ' + (gains.slice(0, 8).map(g => `${g[0]} ${g[2]}→${g[3]}kg`).join('; ') || 'none') + '.');
  const bl = bodyLog.slice().sort((a, b) => a.date.localeCompare(b.date)); if (bl.length >= 2) L.push(`Body weight: ${bl[0].kg}kg (${bl[0].date}) to ${bl[bl.length - 1].kg}kg (${bl[bl.length - 1].date}), ${bl.length} weigh-ins.`);
  try { pathTick(true); const D = pathData().done, c = PATH_STAGES.find(s => !D[s.id]); L.push(`Training Path: ${Object.keys(D).length}/${PATH_STAGES.length} stages cleared${c ? '; next objective: ' + c.obj : ''}.`); } catch(e){}
  return L.join('\n');
}
