  const out = $('vRes'); const say = (t, ok) => { if (out) out.innerHTML = `<div class="vres ${ok ? 'ok' : 'bad'}">${t}</div>`; };
  if (!pick) return say('⚠️ ' + escapeHTML(tr('Did not understand. Say: exercise, weight, reps.')) + '<br><small>' + escapeHTML(alts[0] || '') + '</small>', false);
  if (!pick.b){ const all = state.days.flatMap(d => d.exercises.map(e => ({e, d}))).filter(x => voiceScore(pick.r.text || pick.a, x.e.name) >= 8)[0];
    return say('⚠️ ' + escapeHTML(all ? tr('That exercise is in another day. Open it first:') + ' ' + all.d.name : tr('No matching exercise in the day on screen')) + '<br><small>' + escapeHTML(pick.a) + '</small>', false); }
  const {r, b} = pick, undo = voiceApply(r, b);
  const sum = `${escapeHTML(b.ex.name)} · ${r.weight !== null ? r.weight + ' kg' : ''}${r.weight !== null && r.reps !== null ? ' × ' : ''}${r.reps !== null ? r.reps : ''}${r.sets > 1 ? ' · ' + r.sets + '×' : ''}`;
  VLAST = {b, undo};
  say('✅ ' + sum + ' <button type="button" id="vUndo" class="sec tiny">↩ ' + escapeHTML(tr('Undo')) + '</button>', true);
  if ($('vUndo')) $('vUndo').onclick = () => { voiceUndo(VLAST.b, VLAST.undo); if ($('vRes')) $('vRes').innerHTML = ''; };
