function ivBeep(at, f, dur, vol){ try { const o = IVAC.createOscillator(), g = IVAC.createGain(); o.type = 'square'; o.frequency.value = f; o.connect(g); g.connect(IVAC.destination); g.gain.setValueAtTime(0.0001, at); g.gain.exponentialRampToValueAtTime(vol || .5, at + .01); g.gain.exponentialRampToValueAtTime(.0001, at + dur); o.start(at); o.stop(at + dur + .02); IVNODES.push(o); } catch(e){} }
