  if ($('scFile')) $('scFile').onchange = async e => { const f = e.target.files[0]; if (!f) return; try { const bmp = await createImageBitmap(f), r = await det.detect(bmp); if (r && r[0]) scanHandle(r[0].rawValue); else $('scRes').innerHTML = `<div class="vres bad">⚠️ ${escapeHTML(tr('No code found in the photo'))}</div>`; } catch(err){ $('scRes').innerHTML = `<div class="vres bad">⚠️ ${escapeHTML(tr('No code found in the photo'))}</div>`; } e.target.value = ''; };
