const ACCENTS = {brass:['#8c6615', '#d8ac52', 'Brass'], steel:['#2a63a8', '#6aa6ee', 'Steel'], emerald:['#1f7a52', '#4fd08e', 'Emerald'], crimson:['#b3363f', '#ff7b84', 'Crimson'], violet:['#6b4fd1', '#a58cff', 'Violet'], ember:['#a84a0c', '#ff9a52', 'Ember']};
