    const g = muscleOf(e.name) || '', rom = KC_ROM[g] || .45, comp = KC_COMP.test(e.name) && !KC_ISO.test(e.name), bw1 = KC_BW1.test(e.name), bw2 = !bw1 && KC_BW2.test(e.name), b = best[String(e.name).trim().toLowerCase()] || 0;
