(function(){
  const OK = /^(▶|✅|＋|➕|📥|⬆️)?\s*(Start|Log|Claim|Join|Import|Save|Use this|Add|Create|Done|Resume|Buy|Unlock|Generate|Next|Finish)/i, BAD = /^(⏹|🗑️|✕|❌)?\s*(Stop|Leave|Delete|Remove|Reset|Discard|Clear)/i, INFO = /^(📤|🔗|📋|⬇️|🔄|📷|🎤)?\s*(Share|Invite|Copy|Export|Refresh|Analyze|Scan|Send|Download|Voice)/i;
  const skip = b => b.dataset.tone || b.classList.contains('tab') || b.classList.contains('icon') || b.classList.contains('cchip') || b.classList.contains('qchip') || b.classList.contains('tclose') || b.closest('#timer,.tabs,.subnav,.seg,.cchips,.stepper,.gs-cats');
  function tone(root){ (root.querySelectorAll ? [...root.querySelectorAll('button'), ...(root.tagName === 'BUTTON' ? [root] : [])] : []).forEach(b => { if (skip(b)) return; const t = (b.textContent || '').trim(); if (!t || t.length > 40) return; if (BAD.test(t)) b.dataset.tone = 'bad'; else if (INFO.test(t) && !b.classList.contains('sec')) b.dataset.tone = 'info'; else if (OK.test(t) && !b.classList.contains('sec') && !b.classList.contains('tiny')) b.dataset.tone = 'ok'; }); }
  tone(document.body); let q = 0; new MutationObserver(ms => { if (q) return; q = setTimeout(() => { q = 0; tone(document.body); }, 120); }).observe(document.body, {childList:true, subtree:true});
  document.addEventListener('pointerdown', e => { if (e.target.closest && e.target.closest('button,.qrow,.cchip,.xrow,.gs-it,.sn-it')){ try { navigator.vibrate && (!navigator.userActivation || navigator.userActivation.hasBeenActive) && navigator.vibrate(6); } catch(_){} } }, {passive:true});
})();
