  const hostTab = n => document.querySelector('.tab[data-tab="' + n + '"]');
  hostTab('store').addEventListener('click', () => { try { renderStore(); } catch(e){ console.error(e); } try { charMascots(); } catch(e){} });

  /* header: library + store next to search and settings */
