    const mkb = (id, ic, label, tab) => { const b = document.createElement('button'); b.type = 'button'; b.className = 'gear hbtn'; b.id = id; b.setAttribute('aria-label', label); b.innerHTML = ic; b.onclick = () => { buzz(8); hostTab(tab).click(); }; return b; };
