const dayOf = k => NU.days[k] || (NU.days[k] = {meals:[], water:0});
const r1 = x => Math.round((+x || 0) * 10) / 10;
const fmt = n => Math.round(+n || 0).toLocaleString(LOCALE());
const sumM = ms => ms.reduce((a, m) => ({cal:a.cal + (+m.cal || 0), p:a.p + (+m.p || 0), c:a.c + (+m.c || 0), f:a.f + (+m.f || 0)}), {cal:0, p:0, c:0, f:0});
