  [['p', 'nfP', 0, 600], ['c', 'nfC', 0, 1200], ['f', 'nfF', 0, 400]].forEach(([k, id, lo, hi]) => { const x = n(id, lo, hi); if (x === null || x === 0) delete s[k]; else s[k] = Math.round(x); });
