  get_plan:{r:1, d:'Read the full workout plan: days with exercises, sets, reps and weight (kg).', a:'', run:() => OK('', null, state.days.map(d => ({day:d.name, exercises:(d.exercises || []).map(e => ({name:e.name, sets:e.sets, reps:e.reps, kg:e.weight}))})))},
