  add_exercise:{risk:'mid', d:'Add an exercise to a plan day (creates the day if missing). Weight in kg.', a:'day, exercise, sets?, reps?, kg?', label:a => '➕ ' + String(a.day || '') + ': ' + I('add') + ' ' + String(a.exercise || '') + ' ' + [a.sets ? a.sets + '×' : '', a.reps || '', a.kg ? '@' + a.kg + 'kg' : ''].join(''), run:a => { const nm = String(a.exercise || '').trim().slice(0, 50); if (!nm || !String(a.day || '').trim()) return NO(I('Day and exercise are required')); const u = planSnap(); let d = dayBy(a.day); if (!d){ d = {id:makeId(), name:String(a.day).trim().slice(0, 30), color:'#3a7bd5', exercises:[]}; state.days.push(d); } if (exBy(d, nm)) return NO(I('Already in the plan') + ': ' + nm); d.exercises.push({name:nm, sets:Math.round(num(a.sets, 1, 20, 3)), reps:String(a.reps || '8–12').slice(0, 12), weight:num(a.kg, 0, 1000, 20)}); save(); renderAllViews(); return OK(d.name, u); }},
