const T = (en, ar) => LANG === 'ar' ? ar : en;
const catOf = m => { const f = m.fk && getFood(m.fk); return f ? f.cat : ''; };
function insights(){
  const out = [], k = todayKey(), S = statsFor(14), S7 = statsFor(7), tgT = targetFor(k), tot = sumM(peek(k).meals), hr = new Date().getHours();
  const add = (e, tone, en, ar, ask) => out.push({e, tone, t:T(en, ar), ask});
  if (!hasGoal()) add('🎯', 'warn', 'You have no calorie goal yet. Set one so every number in the app means something.', 'لسه ما حددتش هدف سعرات. حدده عشان كل الأرقام تبقى ليها معنى.', 'Set my calorie and protein goals for me');
  const lg = S.rows.filter(r => r.n > 0); if (!lg.length) return out;
  if (peek(k).meals.length && hr >= 13 && tgT.p - tot.p >= 25) add('🥩', 'warn', `Protein is ${Math.round(tgT.p - tot.p)} g short today. Add a high-protein meal or snack.`, `ناقصك ${Math.round(tgT.p - tot.p)} جم بروتين النهارده. ضيف وجبة أو سناك عالي البروتين.`, 'What should I eat to finish today\'s protein?');
  if (S7.logged >= 3){
    const diff = (S7.avg.cal - S7.tgAvg) / S7.tgAvg;
    if (diff > .08) add('🔥', 'warn', `You average ${fmt(S7.avg.cal)} kcal, ${Math.round(diff * 100)}% above your goal this week.`, `متوسطك ${fmt(S7.avg.cal)} سعرة، أعلى من هدفك بـ ${Math.round(diff * 100)}% الأسبوع ده.`, 'I am eating above my goal. Where can I cut calories without losing muscle?');
    else if (diff < -.12) add('⚠️', 'warn', `You average ${fmt(S7.avg.cal)} kcal, ${Math.round(-diff * 100)}% under your goal. Eating too little slows recovery and gains.`, `متوسطك ${fmt(S7.avg.cal)} سعرة، أقل من هدفك بـ ${Math.round(-diff * 100)}%. الأكل القليل بيبطّأ التعافي والنتايج.`, 'I am eating under my goal. How do I add calories easily?');
    else add('✅', 'good', `Your week is on target: ${fmt(S7.avg.cal)} kcal average vs ${fmt(S7.tgAvg)} goal.`, `أسبوعك على الهدف: متوسط ${fmt(S7.avg.cal)} سعرة مقابل هدف ${fmt(S7.tgAvg)}.`);
    const pr = S7.pHit / S7.logged; if (pr < .5) add('🥩', 'warn', `You hit your protein on only ${S7.pHit} of ${S7.logged} logged days.`, `وصلت لهدف البروتين في ${S7.pHit} بس من ${S7.logged} أيام.`, 'Give me easy ways to raise my protein every day'); else if (pr >= .8) add('💪', 'good', `Protein on target ${S7.pHit} of ${S7.logged} days. Great for muscle.`, `البروتين على الهدف ${S7.pHit} من ${S7.logged} أيام. ممتاز للعضل.`);
  }
  if (S7.logged < 4) add('📅', 'info', `You logged ${S7.logged} of the last 7 days. Logging most days makes the insights accurate.`, `سجلت ${S7.logged} من آخر 7 أيام. التسجيل أغلب الأيام بيخلي التحليلات أدق.`);
  else if (S7.logged === 7) add('🔥', 'good', 'You logged all 7 days. Perfect consistency.', 'سجلت الـ7 أيام كلهم. التزام ممتاز.');
  const wk = lg.filter(r => { const d = new Date(r.k + 'T12:00:00').getDay(); return d === 5 || d === 6; }), wd = lg.filter(r => { const d = new Date(r.k + 'T12:00:00').getDay(); return d !== 5 && d !== 6; });
  if (wk.length >= 2 && wd.length >= 4){ const a = wk.reduce((s, r) => s + r.cal, 0) / wk.length, b = wd.reduce((s, r) => s + r.cal, 0) / wd.length; if (a > b * 1.18) add('🎉', 'info', `Weekends run ${fmt(a - b)} kcal higher than weekdays. Plan for it so it does not erase your week.`, `أيام الجمعة والسبت أعلى بـ ${fmt(a - b)} سعرة من باقي الأسبوع. خطط لها عشان ما تبوّظش أسبوعك.`, 'Help me plan my weekend meals so I stay on track'); }
  let late = 0, all = 0; lg.forEach(r => peek(r.k).meals.forEach(m => { all += m.cal; if (m.t && m.src !== 'copy'){ const h = new Date(m.t).getHours(); if (h >= 22 || h < 4) late += m.cal; } }));
  if (all && late / all > .25) add('🌙', 'warn', `${Math.round(late / all * 100)}% of your calories are logged after 10 pm.`, `${Math.round(late / all * 100)}% من سعراتك متسجلة بعد 10 بالليل.`, 'I eat a lot late at night. How do I fix that?');
  if (S7.logged >= 3){ const avgW = S7.rows.filter(r => r.n).reduce((s, r) => s + r.water, 0) / S7.logged, wt = ST().water || 8; if (avgW < wt * .6) add('💧', 'warn', `Water averages ${avgW.toFixed(1)} of ${wt} glasses. Hydration affects strength and appetite.`, `الماء بمتوسط ${avgW.toFixed(1)} من ${wt} أكواب. الترطيب بيأثر على القوة والشهية.`); else if (avgW >= wt) add('💧', 'good', 'You are hitting your water goal. Keep it up.', 'بتحقق هدف الماء. كمل كده.'); }
  const tr_ = lg.filter(r => trainedOn(r.k)), rs = lg.filter(r => !trainedOn(r.k));
  if (tr_.length >= 2 && rs.length >= 2){ const a = tr_.reduce((s, r) => s + r.cal, 0) / tr_.length, b = rs.reduce((s, r) => s + r.cal, 0) / rs.length; if (a < b - 50) add('🏋️', 'info', `You eat ${fmt(b - a)} kcal less on training days than on rest days. Fuel your workouts.`, `بتاكل ${fmt(b - a)} سعرة أقل في أيام التمرين عن أيام الراحة. غذّي تمرينك.`, 'How should I eat on training days vs rest days?'); else if (a > b + 100) add('🏋️', 'good', `You eat ${fmt(a - b)} kcal more on training days. Smart fueling.`, `بتاكل ${fmt(a - b)} سعرة زيادة في أيام التمرين. تغذية ذكية.`); }
  const byF = {}; lg.forEach(r => peek(r.k).meals.forEach(m => { const n = iname(m); byF[n] = (byF[n] || 0) + m.cal; }));
  const top = Object.entries(byF).sort((a, b) => b[1] - a[1]).slice(0, 3); if (top.length >= 2 && all) add('📊', 'info', `Top calorie sources: ${top.map(x => x[0] + ' (' + Math.round(x[1] / all * 100) + '%)').join(', ')}.`, `أكتر مصادر السعرات: ${top.map(x => x[0] + ' (' + Math.round(x[1] / all * 100) + '%)').join('، ')}.`);
  let junk = 0; lg.forEach(r => peek(r.k).meals.forEach(m => { if (['sweets', 'snacks', 'sauces'].includes(catOf(m))) junk += m.cal; })); if (all && junk / all > .3) add('🍰', 'warn', `${Math.round(junk / all * 100)}% of your calories come from sweets, snacks and sauces.`, `${Math.round(junk / all * 100)}% من سعراتك من حلويات وسناكس وصلصات.`, 'Suggest healthier swaps for my sweets and snacks');
  let vg = 0; lg.forEach(r => peek(r.k).meals.forEach(m => { if (['veg', 'fruit'].includes(catOf(m))) vg++; })); if (lg.length >= 4 && vg / lg.length < 2) add('🥦', 'info', 'Few vegetables and fruit in your log. Fibre helps hunger and digestion.', 'خضار وفاكهة قليلة في سجلك. الألياف بتساعد على الشبع والهضم.', 'Help me add more vegetables and fruit easily');
  const ad = adaptive(); if (!ad.need){ const md = ST().mode || 'maintain';
    if (md === 'cut' && ad.perWeek > .1) add('⚖️', 'warn', `Goal is fat loss but your weight is rising ${ad.perWeek} ${unitName()}/week. Your real maintenance is about ${fmt(ad.tdee)} kcal.`, `هدفك تنشيف بس وزنك بيزيد ${ad.perWeek} ${unitName()} في الأسبوع. سعراتك الحقيقية للثبات حوالي ${fmt(ad.tdee)}.`, 'My weight is not going down on my cut. Fix my plan');
    else if (md === 'bulk' && ad.perWeek < .05) add('⚖️', 'warn', `Goal is muscle gain but weight is flat. Add about ${Math.max(150, Math.round(ad.tdee * 1.08 - ad.intake))} kcal per day.`, `هدفك زيادة عضل بس الوزن ثابت. زوّد حوالي ${Math.max(150, Math.round(ad.tdee * 1.08 - ad.intake))} سعرة يوميًا.`, 'My weight is not going up on my bulk. Fix my plan');
    else add('🧠', 'info', `Your real maintenance is about ${fmt(ad.tdee)} kcal (weight ${ad.perWeek > 0 ? '+' : ''}${ad.perWeek} ${unitName()}/week).`, `سعراتك الحقيقية للثبات حوالي ${fmt(ad.tdee)} (الوزن ${ad.perWeek > 0 ? '+' : ''}${ad.perWeek} ${unitName()} في الأسبوع).`); }
  const bf = []; lg.forEach(r => { const b = peek(r.k).meals.filter(m => m.meal === 'breakfast'); if (b.length) bf.push(sumM(b).p); }); if (bf.length >= 3){ const a = bf.reduce((s, x) => s + x, 0) / bf.length; if (a < 15) add('🍳', 'info', `Breakfast has only ${Math.round(a)} g protein on average. Spreading protein across meals helps muscle.`, `الفطار فيه ${Math.round(a)} جم بروتين بس في المتوسط. توزيع البروتين على الوجبات بيفيد العضل.`, 'Give me high-protein breakfast ideas'); }
  const o = {warn:0, info:1, good:2}; return out.sort((a, b) => o[a.tone] - o[b.tone]).slice(0, 10);
}
const insHtml = (L, n) => L.slice(0, n || 99).map((x, i) => `<div class="nf-ins ${x.tone}"><i>${x.e}</i><span>${E(x.t)}</span>${x.ask ? `<button type="button" data-tone="none" data-a="insask" data-i="${i}" aria-label="Ask AI">🤖</button>` : ''}</div>`).join('');

