    if (!o.m) try { const u = navigator.userAgentData; if (u && u.getHighEntropyValues){ const h = await u.getHighEntropyValues(['model', 'platformVersion']); o.m = h.model || ''; o.o = ((u.platform || '') + ' ' + (h.platformVersion || '')).trim(); } } catch(e){}
